parameters.jsCode:
const input = $('Normalizar email').first().json;
const rows = $input.all().map(i => i.json).filter(r => r && r['Session_ID'] === input.session_id);
const m = rows[0] ?? {};
return [{ json: {
  ...input,
  memoria_existe: Boolean(m['Session_ID']),
  resumen_consolidado: m['Resumen consolidado'] && m['Resumen consolidado'] !== 'Sin memoria previa' ? m['Resumen consolidado'] : '',
  estado_caso: m['Estado del caso'] || 'NUEVO',
  datos_clave: m['Datos clave'] || '',
  historial_pendiente: m['Historial pendiente'] || '',
  contador_mensajes: Number(m['Mensajes'] || 0),
  mensajes_desde_resumen: Number(m['Mensajes desde resumen'] || 0)
}}];

const source = $('Preparar memoria').first().json;
const out = $json.output ?? {};
const allowed = ['CONSULTA', 'SOLICITUD_CAMBIO', 'FUERA_DE_ALCANCE'];
return [{ json: {
  ...source,
  output: {
    ...out,
    intent: allowed.includes(out.intent) ? out.intent : 'FUERA_DE_ALCANCE',
    confidence_score: Math.max(0, Math.min(1, Number(out.confidence_score ?? 0)))
  }
}}];

const base = $('Preparar memoria').first().json;
return $input.all().map(item => {
  const j = { ...base, ...item.json };
  const pendiente = [
    base.historial_pendiente || '',
    `Usuario: ${base.original_input}\nAgente: ${j.respuesta || ''}`
  ].filter(Boolean).join('\n---\n');
  const n = Number(base.mensajes_desde_resumen || 0) + 1;
  return { json: {
    ...j,
    contador_mensajes: Number(base.contador_mensajes || 0) + 1,
    mensajes_desde_resumen: n,
    historial_pendiente: pendiente,
    requiere_resumen: n > 5
  }};
});

