Devolvé SOLO JSON válido: {"asunto_principal":"","puntos_clave":[],"accion_requerida":"","estado_caso":""}

parameters.jsCode:
const base = $('Preparar respuesta final y contador').first().json;
const raw = $json.text ?? $json.output ?? $json.response ?? '';
let d;
try {
  d = JSON.parse(String(raw).replace(/^```(?:json)?\s*/i, '').replace(/```$/, '').trim());
} catch (e) {
  // Si el JSON falla: no se guarda la conversación como resumen.
  // Se conserva la memoria previa y el historial, y se reintenta en el próximo mail.
  return [{ json: {
    ...base,
    fecha_actualizacion: $now.setZone('Europe/Madrid').toFormat('dd/MM/yyyy HH:mm')
  }}];
}
return [{ json: {
  ...base,
  resumen_consolidado: [d.asunto_principal, ...(Array.isArray(d.puntos_clave) ? d.puntos_clave : []), d.accion_requerida].filter(Boolean).join(' | '),
  datos_clave: JSON.stringify({ puntos_clave: d.puntos_clave ?? [], accion_requerida: d.accion_requerida ?? '' }),
  estado_caso: d.estado_caso || base.estado_caso || 'EN_PROCESO',
  historial_pendiente: '',
  mensajes_desde_resumen: 0,
  fecha_actualizacion: $now.setZone('Europe/Madrid').toFormat('dd/MM/yyyy HH:mm')
}}];

